var SPC={"Amoeboid (DM14)":{"size":"Medium","speed":30,"dark":0,"type":"Humanoid","traits":[["Flexible Form","As an action, shape your body into any static form no larger than 8 ft in any dimension. You copy only its basic shape, not color, texture, moving parts or fine detail. You cannot change your volume, and you cannot move, attack or cast spells while in a static shape. You can also use an action to touch a living creature and take on its general form. Your size and other statistics stay the same. You can speak and understand its language, and if it has a burrowing, climbing or swimming speed you gain it, up to 40 ft. You can make the same actions that creature could, other than ones needing special features."],["Amorphous","You can squeeze through a space 1 inch wide. You cannot expand in a space that resists you."],["Reform","When you take Bludgeoning, Piercing or Slashing damage from a nonmagical weapon and do not drop to 0 hit points, you can use your reaction to regain 1d4 hit points, up to the damage taken."],["Languages","You speak, read and write Common and Amoeboid. Others can only approximate Amoeboid, since it is made with a fluid body. In a changed shape you also speak that creature's language."]],"hb":"DM14","asi":{"INT":2,"CON":1},"lgf":["Common","Amoeboid"]},"Avia-Ra (DM14)":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","skills":["Religion"],"profs":{"weapons":"Sunstaff, Scimitar, Shortbow, Spear, Whip"},"spAb":"WIS","traits":[["Darkvision","Darkvision out to 60 ft."],["Avia-Ra Weapon Training","Proficiency with the sunstaff, scimitar, shortbow, spear and whip."],["Doctrine","Proficiency in the Religion skill."],["Blessings of the Sun","You can cast bless on yourself only, with no slot. Wisdom is the spellcasting ability. While it lasts, if you roll a 4 on the d4 you add to an attack roll or save, you have Advantage on that roll. Long Rest to use again."],["Sun's Chosen","You know the sacred flame and thaumaturgy cantrips. Wisdom is the spellcasting ability for them."],["Languages","You speak, read and write Common and Avia-Ra, a soft language of long vowels. It is written in the Celestial script."]],"hb":"DM14","asi":{"WIS":2,"DEX":1},"lgf":["Common","Avia-Ra"]},"Nautilid (DM14)":{"size":"Medium","speed":30,"dark":0,"type":"Humanoid","skills":["Investigation"],"fx":{"moves":{"swim":30}},"traits":[["Amphibious","You can breathe water as well as air, though air is uncomfortable for you without help."],["Powerful Build","You count as one size larger for carrying capacity and for the weight you can push, drag or lift."],["Deductive","Proficiency in the Investigation skill."],["Aqua Suit","Except aboard a whorl ship, you wear a bulky aqua suit filled with Poseidon Solution so you can breathe comfortably. It covers your whole body, including a domed helmet. Without it you can still breathe air or water, but air reaches your lungs poorly, much like thin air does for a human. You can don or doff the helmet as part of an action on your turn, and the whole suit in 1 minute. If damaged but not destroyed, it mends itself. While you wear it, your AC is 13 + your Dexterity modifier, and other armor can be fitted around it at no cost. With no other armor fitted, you count as unarmored for features like Unarmored Defense. You also have Resistance to Fire damage. The suit counts as a life suit and has an embedded universal translator you can use at will."],["Languages","You speak, read and write Common and Aquan."]],"hb":"DM14","asi":{"STR":2,"INT":1},"lgf":["Common","Aquan"]},"Near-Human":{"size":"Medium","speed":30,"dark":0,"type":"Humanoid","featPick":true,"skillPick":{"n":1,"from":["Acrobatics","Animal Handling","Arcana","Athletics","Deception","History","Insight","Intimidation","Investigation","Medicine","Nature","Perception","Performance","Persuasion","Religion","Sleight of Hand","Stealth","Survival"],"label":"Skills"},"asiFlex":2,"traits":[["Ability Score Increase","Two different ability scores of your choice rise by 1. This replaces the human trait of the same name."],["Skills","You have proficiency in one skill of your choice."],["Feat","You gain one feat of your choice. It must list Near-Human variant as a prerequisite."],["Languages","You speak, read and write Common and one other language of your choice."]],"hb":"DM14","lgf":["Common"],"lgn":1},"Orc (DM14)":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","profs":{"tools":"Ship Maintenance Tools"},"skillPick":{"n":1,"from":["Athletics","Intimidation","Piloting","Technology"],"label":"Know-How"},"traits":[["Darkvision","Darkvision out to 60 ft."],["Follow Through","Once per turn, you can reroll one damage die for an attack with a heavy weapon."],["Gearhead","Building rides is an orc pastime. You have proficiency with ship maintenance tools and Advantage on checks to repair or modify a ship."],["Know-How","Proficiency in one skill of your choice from Athletics, Intimidation, Piloting and Technology."],["Powerful Build","You count as one size larger for carrying capacity and for the weight you can push, drag or lift."],["Languages","You speak, read and write Common and Orc."]],"hb":"DM14","asi":{"STR":2,"CON":1},"lgf":["Common","Orc"]},"Skathári (DM14)":{"size":"Medium","speed":30,"dark":0,"type":"Humanoid","fx":{"moves":{"climb":20}},"traits":[["Adaptive Metabolism","Extreme temperatures in space and other harsh environments do not harm you. You can hold your breath for 10 times your Constitution modifier in minutes (minimum 10). You have Advantage on ability checks and saves against inhaled poisons and gases."],["Gliding Wings","Your membranous wings let you glide clumsily. While falling, you can move up to 10 ft horizontally for every 5 ft you fall, up to your speed. You have Resistance to Bludgeoning, Piercing and Slashing damage from falling."],["Powerful Build","You count as one size larger for carrying capacity and for the weight you can push, drag or lift."],["Hooked Claws","Your fingers end in short hooked claws. You have a climbing speed of 20 ft, and your unarmed strikes can deal Slashing damage instead of Bludgeoning."],["Regenerative","If a body part is amputated without killing you, you regrow it fully in 24 hours."],["Languages","You speak, read and write Common and Skathári, a choppy, syllabic language full of idiom and metaphor."]],"hb":"DM14","asi":{"STR":2,"CON":1},"lgf":["Common","Skathári"]},"Vect (DM14)":{"size":"Medium","speed":30,"dark":0,"type":"Construct","traits":[["Reconfigurable Ability Score Increase","One ability score of your choice other than Constitution rises by 1. You can change the choice after a Long Rest, and no score can pass 20 this way."],["Thermalsight","You see living creatures through darkness and heavy obscurement such as fog out to 30 ft, and tell whether a creature is alive or dead by body heat. You cannot see color, illusions, invisibility or through magical darkness. One inch of solid barrier blocks it."],["Construct Anatomy","You are a living creature despite being built. You are immune to nonmagical diseases and need no food, drink or air, though you can eat and drink. You have Advantage on saves against exhaustion. Instead of sleeping you stay inactive 4 hours a day, fully aware of your surroundings. Sleep magic can still put you in torpor."],["Inflexible Mind","You have Advantage on saves against being Charmed."],["Embedded Armor","You can install armor plating as a construct graft in the External slot. At level 1 choose one type, and you can install others you find. Velocity Plating: speed +5 ft and long jump +5 ft. Composite Plating: AC 13 + your Dexterity modifier. Juggernaut Plating: AC 16, but you cannot wear conventional armor with it, and you need heavy armor proficiency to install it."],["Languages","You speak, read and write Common."]],"hb":"DM14","asi":{"CON":2},"asiPick":{"n":1,"v":1,"ex":["CON"]},"lgf":["Common"]},"Wrothian (DM14)":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","traits":[["Darkvision","Darkvision out to 60 ft."],["Neural Lock","As an action, freeze the nervous system of a humanoid you see within 60 ft. It makes a Wisdom save (DC 8 + your Constitution modifier + Proficiency Bonus). On a failure it is Incapacitated and its speed is 0 until the start of your next turn. Long Rest to use again."],["Razor Teeth","Your claws and teeth are natural weapons for unarmed strikes. A hit deals Slashing or Piercing damage (your choice) equal to 1d4 + your Strength modifier."],["Repletion","Your body runs on psionic energy absorbed aboard your ship. You need no food or drink, though you can eat and drink."],["Telepathy","You can speak telepathically to one creature at a time within 30 ft. It understands you only if you share a language."],["Languages","You speak, read and write Common and Wrothian, a rare language of rumbles, sibilants and chirps written in circular runes."]],"hb":"DM14","asi":{"DEX":2,"CHA":1},"lgf":["Common","Wrothian"]},"Star Dwarf":{"size":"Medium","speed":25,"dark":60,"type":"Humanoid","skills":["Technology"],"profs":{"weapons":"Battleaxe, Handaxe, Light Hammer, Warhammer","tools":"Ship Maintenance Tools"},"traits":[["Darkvision","Darkvision out to 60 ft."],["Dwarven Resilience","Resistance to Poison damage and Advantage on saves to avoid or end the Poisoned condition."],["Dwarven Combat Training","Proficiency with the Battleaxe, Handaxe, Light Hammer and Warhammer."],["Tool Proficiency","Proficiency with one of Smith's Tools, Brewer's Supplies or Mason's Tools."],["Stonecunning","On an Intelligence (History) check about the origin of stonework, you count as proficient and add double your Proficiency Bonus."],["Unhindered Pace","Heavy armor does not reduce your speed, and high or extreme gravity does not either."],["Dwarven Engineering Training","Proficiency in Technology and with ship maintenance tools."]],"hb":"DM14","asi":{"CON":2,"STR":2},"lgf":["Common","Dwarvish"]},"Drow; Star Elf":{"size":"Medium","speed":30,"dark":90,"type":"Humanoid","skills":["Perception"],"profs":{"weapons":"Laser Halfsword, Laser Sword, Photonic Lash, Swarm Pistol"},"traits":[["Keen Senses","Proficiency in the Perception skill."],["Fey Ancestry","You have Advantage on saves to avoid or end the Charmed condition, and magic cannot put you to sleep."],["Trance","You do not sleep. You meditate for 4 hours instead, and finish a Long Rest after that time."],["Star Elf Weapon Training","Proficiency with the laser halfsword, laser sword, photonic lash and swarm pistol."],["Nocturnal Vision","Your Darkvision reaches 90 ft. You have Disadvantage on Wisdom (Perception) checks that rely on sight while in bright light."],["Covert","When you are hidden and a creature finds you with a Wisdom (Perception) check, you can try your Dexterity (Stealth) check again. On a success you silently move and it does not notice you. Short or Long Rest to use again."],["Drow Subtlety","When you hide, conceal a weapon or take any action contested by a creature's passive Perception, you can subtract 5 from that score."]],"hb":"DM14","asi":{"DEX":2,"CHA":1},"lgf":["Common","Elvish"]},"Fey; Star Elf":{"size":"Medium","speed":30,"dark":60,"type":"Humanoid","skills":["Perception"],"profs":{"weapons":"Longsword, Shortsword, Shortbow, Longbow"},"spAb":"CHA","skillPick":{"n":1,"from":["Arcana","Data","Technology"],"label":"Academic Interest"},"traits":[["Darkvision","Darkvision out to 60 ft."],["Keen Senses","Proficiency in the Perception skill."],["Fey Ancestry","You have Advantage on saves to avoid or end the Charmed condition, and magic cannot put you to sleep."],["Trance","You do not sleep. You meditate for 4 hours instead, and finish a Long Rest after that time."],["Traditional Elf Weapon Training","Proficiency with the longsword, shortsword, shortbow and longbow."],["Academic Interest","Proficiency in your choice of Arcana, Data or Technology."],["Fey Arcana","You know the minor illusion cantrip. At level 3 you can cast faerie fire once, and at level 5 misty step once, each regained on a Long Rest. Charisma is the spellcasting ability."]],"hb":"DM14","asi":{"DEX":2,"INT":1},"lgf":["Common","Elvish"]},"Wood; Star Elf":{"size":"Medium","speed":35,"dark":60,"type":"Humanoid","skills":["Perception","Piloting"],"profs":{"weapons":"Laser Halfsword, Laser Sword, Photonic Lash, Swarm Pistol","tools":"Ship Maintenance Tools"},"traits":[["Darkvision","Darkvision out to 60 ft."],["Keen Senses","Proficiency in the Perception skill."],["Fey Ancestry","You have Advantage on saves to avoid or end the Charmed condition, and magic cannot put you to sleep."],["Trance","You do not sleep. You meditate for 4 hours instead, and finish a Long Rest after that time."],["Star Elf Weapon Training","Proficiency with the laser halfsword, laser sword, photonic lash and swarm pistol."],["Fleet Feet","Your walking speed is 35 ft."],["Ironwood Shipwright","Proficiency in Piloting and with ship maintenance tools."]],"hb":"DM14","asi":{"DEX":2,"WIS":1},"lgf":["Common","Elvish"]},"Star Gnome":{"size":"Small","speed":25,"dark":60,"type":"Humanoid","profs":{"tools":"Circuitry Kit"},"traits":[["Darkvision","Darkvision out to 60 ft."],["Gnome Cunning","Advantage on Intelligence, Wisdom and Charisma saves against magic."],["Retro Technology","On an Intelligence (Technology) check to identify old magical technology, add double your Proficiency Bonus in place of any Proficiency Bonus you would normally add."],["Engineer","Proficiency with the circuitry kit. With it, 1 hour and 10 gp of materials, you build an improvised magical device: a flashlight, a comm set or an igniter. It stops working after 24 hours unless you spend 1 hour repairing it, or when you dismantle it with an action, and you can reclaim the materials. You can have one such device at a time."]],"hb":"DM14","asi":{"INT":2,"CON":1},"lgf":["Common","Gnomish"]},"Star Halfling":{"size":"Small","speed":25,"dark":0,"type":"Humanoid","skills":["Persuasion"],"traits":[["Lucky","When you roll a 1 on an attack roll, ability check or saving throw, reroll the die and use the new roll."],["Brave","Advantage on saves to avoid or end the Frightened condition."],["Halfling Nimbleness","You can move through the space of any creature larger than you."],["Naturally Shrewd","Proficiency in Persuasion. You have Advantage on skill checks involving money, business affairs, legal proceedings or similar dealings."]],"hb":"DM14","asi":{"DEX":2,"CHA":1},"lgf":["Common","Halfling"]}};
